Lemma frame_agree (Ma Mb : word -> option byte) (Wp : Z -> Prop) :
  (forall a, Wp a -> (spc <= a < sp) \/ (F <= a < F + 64) \/ (F / 8 + SB <= a < F / 8 + SB + 8)) ->
